/** 全部图标名（BODIES 的键，声明顺序）。演示站/文档遍历用，避免各处再抄一份清单。 */
export const APP_ICON_NAMES = Object.keys(BODIES) as AppIconName[];

export function AppIcon({
  name,
  size = 16,
  strokeWidth = 1.7,
  className,
  ...props
}: AppIconProps) {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={strokeWidth}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      data-app-icon={name}
      className={className}
      {...props}
      dangerouslySetInnerHTML={{ __html: BODIES[name] }}
    />
  );
}
